  const PRONE = { pel: -90, x: 0, hp: 0, kn: 0, an: 60, sh: 150, el: 140 };
  const SIT = { pel: -2, x: 0, y: 54, lum: -6, footAt: [45, 7.2], footDir: 0, sh: 25, el: 70 };
  const STAND = { pel: 0, x: 0, sh: 4, el: 10 };

  const L = [];

